<template>
  <mobile-bottom-sheet
    ref="bottomSheetRef"
    @onStateChange="handleStateChange"
    @onOpened="handleOpened"
    @onClosed="handleClosed"
    :showDragIndicator="false"
  >
    <div class="admin-list-sheet"
      @touchstart="handleTouchStart"
      @touchmove="handleTouchMove"
      @touchend="handleTouchEnd"
    >
      <!-- 头部 -->
      <div class="sheet-header">
        <div class="header-left">
          <div class="back-btn" @click="handleClose">
            <mobile-l-img src="/static/images/arrow-left.png" w="20px" h="20px" />
          </div>
        </div>
        
        <div class="header-center">
          <h1 class="page-title">{{ $t('adminList') }}</h1>
        </div>
        
        <div class="header-right">
          <div class="create-btn" @click="handleCreate">
            <span class="create-text">{{ $t('create') }}</span>
          </div>
        </div>
      </div>

      <!-- 管理员列表 -->
      <div ref="adminListRef" class="admin-list" @scroll="handleScroll">
        <div
          v-for="admin in adminList"
          :key="admin.id"
          class="admin-item"
        >
          <!-- 用户信息 -->
          <div class="admin-info">
            <!-- 头像 -->
            <div class="avatar-section">
              <div class="avatar">
                <mobile-l-img 
                  :src="admin.avatar || '/static/avatar_def.png'" 
                  w="48px" 
                  h="48px" 
                />
              </div>
            </div>

            <!-- 详细信息 -->
            <div class="user-details">
              <div class="user-name-section">
                <span class="user-name">{{ admin.nickname }}</span>
                <div v-if="admin.is_admin" class="role-badge">
                  <span class="role-text">{{ $t('super') }}</span>
                </div>
              </div>
              <div class="user-email">{{ admin.email }}</div>
            </div>

            <!-- 状态标签 -->
            <div class="status-badge" :class="{ 'status-active': admin.is_active }">
              <span class="status-text" :class="{ 'status-active': admin.is_active }">
                {{ admin.is_active ? $t('active') : $t('inactive') }}
              </span>
            </div>
          </div>

          <!-- 创建时间 -->
          <div class="created-time">
            <span>{{ $t('created') }}: {{ formatDate(admin.created_at) }}</span>
          </div>

          <!-- 操作按钮 -->
          <div class="action-buttons">
            <button 
              class="action-btn reset-btn" 
              :class="{ 'btn-disabled': isResetButtonDisabled(admin.id) }"
              :disabled="isResetButtonDisabled(admin.id)"
              @click="handleReset(admin)"
            >
              <span v-if="isResetButtonDisabled(admin.id)" class="loading-content">
                {{ $t('resetting') }}
                <mobile-l-img src="/static/images/msg-think-loading.png" w="12px" h="12px" class="loading-icon"/>
              </span>
              <span v-else>{{ $t('reset') }}</span>
            </button>
            <button class="action-btn copy-btn" @click="handleCopy(admin)">
              {{ $t('copy') }}
            </button>
            <button 
              class="action-btn"
              :class="[
                admin.is_active ? 'disable-btn' : 'enable-btn',
                { 'btn-disabled': isToggleButtonDisabled(admin.id) }
              ]"
              :disabled="isToggleButtonDisabled(admin.id)"
              @click="handleToggleStatus(admin)"
            >
              <span v-if="isToggleButtonDisabled(admin.id)" class="loading-content">
                {{ admin.is_active ? $t('disabling') : $t('enabling') }}
                <mobile-l-img src="/static/images/msg-think-loading.png" w="12px" h="12px" class="loading-icon"/>
              </span>
              <span v-else>{{ admin.is_active ? $t('disable') : $t('enable') }}</span>
            </button>
          </div>
        </div>

        <!-- 底部状态指示器 -->
        <div class="bottom-status">
          <!-- 加载中状态 -->
          <div v-if="isLoadingMore || isInitialLoading" class="loading-more">
            <span class="loading-text">
              {{ $t('loading') }}
              <mobile-l-img src="/static/images/msg-think-loading.png" w="16px" h="16px" class="loading-icon"/>
            </span>
          </div>
          
          <!-- 没有更多数据 -->
          <div v-else-if="!hasMore && adminList.length > 0" class="no-more-data">
            <span class="no-more-text">{{ $t('noMoreData') }}</span>
          </div>
          
          <!-- 空状态 -->
          <div v-else-if="!isInitialLoading && adminList.length === 0" class="empty-state">
            <p class="empty-text">{{ $t('noAdminData') }}</p>
          </div>      
        </div>
      </div>
    </div>
  </mobile-bottom-sheet>

  <!-- 创建管理员弹窗 -->
  <mobile-create-admin-sheet
    v-model:visible="showCreateAdmin"
    @onAdminCreated="handleAdminCreated"
    @onClose="handleCreateAdminClose"
  />

  <!-- 账户创建成功弹窗 -->
  <mobile-account-success-sheet
    v-model:visible="showAccountSuccess"
    type="create"
    :nickname="newAccountInfo.nickname"
    :email="newAccountInfo.email"
    :password="newAccountInfo.password"
    @onClose="handleAccountSuccessClose"
  />

  <!-- 重置密码成功弹窗 -->
  <mobile-account-success-sheet
    v-model:visible="showResetSuccess"
    type="reset"
    :nickname="resetAccountInfo.nickname"
    :email="resetAccountInfo.email"
    :password="resetAccountInfo.password"
    @onClose="handleResetSuccessClose"
  />
</template>

<script setup>
import { ref, computed, onMounted, onUnmounted, nextTick, watch } from 'vue';
import { useI18n } from 'vue-i18n';
import MobileBottomSheet, { SHEET_STATES } from '@/mobile/components/layout/mobile-bottom-sheet.vue';
import MobileCreateAdminSheet from './mobile-create-admin-sheet.vue';
import MobileAccountSuccessSheet from './mobile-account-success-sheet.vue';
import MobileLImg from '@/mobile/components/mobile-l-img.vue';
import LLoading from '@/components/l-loading.vue';
import { ApiAdmin } from '@/api/api-admin';
import { showUIFeedback } from '@/utils/mobile-ui-feedback';
import { convertUtcToLocal } from '@/utils/util';
import { DATE_FORMATS } from '@/types/date.ts';

const { t } = useI18n();

// props区域
const props = defineProps({
  visible: {
    type: Boolean,
    default: false
  }
});

// emits区域
const emit = defineEmits(['update:visible', 'onClose', 'onOpened', 'onClosed']);

// 变量区域
const adminList = ref([]);
const isInitialLoading = ref(false); // 初始加载状态
const isLoadingMore = ref(false); // 加载更多状态
const hasMore = ref(true); // 是否还有更多数据
const currentPage = ref(1); // 当前页码
const pageSize = 10; // 每页数据量
const adminListRef = ref(null);
const bottomSheetRef = ref(null);

// 创建管理员弹窗控制
const showCreateAdmin = ref(false);

// 账户成功弹窗控制
const showAccountSuccess = ref(false);
const newAccountInfo = ref({
  nickname: '',
  email: '',
  password: ''
});

// 重置密码成功弹窗控制
const showResetSuccess = ref(false);
const resetAccountInfo = ref({
  nickname: '',
  email: '',
  password: ''
});

// 重置密码按钮状态控制
const resettingAdmins = ref(new Set()); // 存储正在重置密码的管理员ID

// 禁用/启用账号按钮状态控制
const togglingAdmins = ref(new Set()); // 存储正在切换状态的管理员ID

// 触摸事件相关变量
const touchStartY = ref(0);
const touchCurrentY = ref(0);
const isDragging = ref(false);
const isInAdminList = ref(false);
const TOUCH_THRESHOLD = 30; // 触发状态切换的滑动阈值（px）

// 计算属性区域
const visible = computed({
  get: () => props.visible,
  set: (value) => emit('update:visible', value)
});

// 判断重置密码按钮是否禁用
const isResetButtonDisabled = (adminId) => {
  return resettingAdmins.value.has(adminId);
};

// 判断禁用/启用按钮是否禁用
const isToggleButtonDisabled = (adminId) => {
  return togglingAdmins.value.has(adminId);
};

// watch 区域
watch(() => props.visible, (newValue) => {
  if (newValue) {
    // 显示时展开到全屏
    nextTick(() => {
      bottomSheetRef.value?.expandUp(SHEET_STATES.FULL);
    });
  } else {
    // 隐藏时收缩
    bottomSheetRef.value?.shrinkDown(SHEET_STATES.HIDDEN);
  }
}, { immediate: true });

// 点击事件区域
const handleClose = () => {
  visible.value = false;
};

const handleCreate = () => {
  showCreateAdmin.value = true;
};

const handleScroll = () => {
  if (!adminListRef.value || isLoadingMore.value || !hasMore.value) return;
  
  const { scrollTop, scrollHeight, clientHeight } = adminListRef.value;
  
  // 当滚动到距离底部30px时触发加载更多
  if (scrollTop + clientHeight >= scrollHeight - 15) {
    loadMoreAdmins();
  }
};

// 触摸事件处理
const handleTouchStart = (e) => {
  touchStartY.value = e.touches[0].clientY;
  touchCurrentY.value = e.touches[0].clientY;
  isDragging.value = false;
  
  // 判断触摸位置是否在admin-list内
  if (adminListRef.value) {
    const rect = adminListRef.value.getBoundingClientRect();
    const touchX = e.touches[0].clientX;
    const touchY = e.touches[0].clientY;
    
    isInAdminList.value = (
      touchX >= rect.left &&
      touchX <= rect.right &&
      touchY >= rect.top &&
      touchY <= rect.bottom
    );
  } else {
    isInAdminList.value = false;
  }
};

const handleTouchMove = (e) => {
  touchCurrentY.value = e.touches[0].clientY;
  const deltaY = touchCurrentY.value - touchStartY.value;
  
  // 如果移动距离超过阈值，认为是拖拽
  if (Math.abs(deltaY) > 5) {
    isDragging.value = true;
  }
};

const handleTouchEnd = (e) => {
  
  if (!isDragging.value || !bottomSheetRef.value) {
    resetTouchState();
    return;
  }
  
  const deltaY = touchCurrentY.value - touchStartY.value;
  const currentState = bottomSheetRef.value.currentState;
  
  // 判断滑动逻辑
  if (isInAdminList.value) {
    // 在admin-list内滑动
    const isAtTop = adminListRef.value && adminListRef.value.scrollTop <= 5;
    
    if (isAtTop && deltaY > TOUCH_THRESHOLD) {
      // 在顶部向下滑动超过阈值
      handleStateSwitch(deltaY, currentState);
    } else if (isAtTop && deltaY < -TOUCH_THRESHOLD) {
      // 在顶部向上滑动超过阈值
      handleStateSwitch(deltaY, currentState);
    }
  } else {
    // 不在admin-list内滑动，直接处理
    if (Math.abs(deltaY) > TOUCH_THRESHOLD) {
      handleStateSwitch(deltaY, currentState);
    }
  }
  
  resetTouchState();
};

// 状态切换处理
const handleStateSwitch = (deltaY, currentState) => {
  if (deltaY > 0) {
    // 向下滑动
    if (currentState === SHEET_STATES.FULL) {
      // 90vh -> 50vh
      bottomSheetRef.value.shrinkDown(SHEET_STATES.HALF);
    } else if (currentState === SHEET_STATES.HALF) {
      // 50vh -> 隐藏
      visible.value = false;
    }
  } else {
    // 向上滑动
    if (currentState === SHEET_STATES.HALF) {
      // 50vh -> 90vh
      bottomSheetRef.value.expandUp(SHEET_STATES.FULL);
    }
  }
};

// 重置触摸状态
const resetTouchState = () => {
  touchStartY.value = 0;
  touchCurrentY.value = 0;
  isDragging.value = false;
  isInAdminList.value = false;
};

// 自定义事件区域
const handleStateChange = (newState) => {
  // 当弹窗状态变为隐藏时，更新父组件的 visible 状态
  if (newState === SHEET_STATES.HIDDEN) {
    emit('update:visible', false);
  }
};

const handleOpened = () => {
  emit('onOpened');
  initAdminList();
  resetTouchState();
};

const handleClosed = () => {
  emit('onClosed');
  resetTouchState();
};

const handleReset = async (admin) => {
  // 如果该管理员正在重置，直接返回
  if (resettingAdmins.value.has(admin.id)) {
    return;
  }
  
  try {
    await showUIFeedback.confirm(
      t('confirmResetPassword'),
      t('passwordReset')
    );
    
    // 添加到重置中集合，禁用按钮
    resettingAdmins.value.add(admin.id);
    
    const response = await ApiAdmin.resetPassword(admin.id);
    
    if (response.code === 200 && response.data) {
      // 设置重置密码账户信息
      resetAccountInfo.value = {
        nickname: response.data.nickname || admin.nickname,
        email: response.data.email || admin.email,
        password: response.data.password || ''
      };
      
      // 显示重置密码成功弹窗
      showResetSuccess.value = true;
      
      // 重新加载列表
      await initAdminList();
    } else {
      showUIFeedback.error(response.message || t('resetError'));
    }
  } catch (error) {
    if (error !== 'cancel') {
      showUIFeedback.error(t('resetError'));
      console.error('Reset password failed:', error);
    }
  } finally {
    // 从重置中集合移除，恢复按钮状态
    resettingAdmins.value.delete(admin.id);
  }
};

const handleCopy = async (admin) => {
  try {
    const textToCopy = `${t('nickname')}: ${admin.nickname}\n${t('email')}: ${admin.email}\n${t('created')}: ${formatDate(admin.created_at)}`;
    
    if (navigator.clipboard) {
      await navigator.clipboard.writeText(textToCopy);
    } else {
      // 兼容旧浏览器
      const textArea = document.createElement('textarea');
      textArea.value = textToCopy;
      document.body.appendChild(textArea);
      textArea.select();
      document.execCommand('copy');
      document.body.removeChild(textArea);
    }
    
    showUIFeedback.success(t('accountCopied'));
  } catch (error) {
    showUIFeedback.error(t('copyFailed'));
    console.error('Copy failed:', error);
  }
};

const handleToggleStatus = async (admin) => {
  // 如果该管理员正在切换状态，直接返回
  if (togglingAdmins.value.has(admin.id)) {
    return;
  }
  
  const isDisabling = admin.is_active;
  const confirmMessage = isDisabling ? t('confirmDisableAccount') : t('confirmEnableAccount');
  
  try {
    await showUIFeedback.confirm(confirmMessage, t('confirmOperation'));
    
    // 添加到切换中集合，禁用按钮
    togglingAdmins.value.add(admin.id);
    
    let response;
    if (isDisabling) {
      response = await ApiAdmin.deactivateAdmin(admin.id);
    } else {
      response = await ApiAdmin.activateAdmin(admin.id);
    }
    
    if (response.code === 200) {
      showUIFeedback.success(
        isDisabling ? t('accountDisabled') : t('accountEnabled')
      );
      // 重新加载列表以获取最新状态
      await initAdminList();
    } else {
      showUIFeedback.error(response.message || t('statusError'));
    }
  } catch (error) {
    if (error !== 'cancel') {
      showUIFeedback.error(t('statusError'));
      console.error(`Toggle admin status failed:`, error);
    }
  } finally {
    // 从切换中集合移除，恢复按钮状态
    togglingAdmins.value.delete(admin.id);
  }
};

// 业务逻辑区域
const initAdminList = async () => {
  // 重置分页状态
  currentPage.value = 1;
  hasMore.value = true;
  adminList.value = [];
  
  await loadAdminList();
};

const loadAdminList = async () => {
  try {
    isInitialLoading.value = true;
    const params = {
      page_size: pageSize,
      page: currentPage.value,
    };
    const response = await ApiAdmin.getAdminList(params);
    
    if (response.code === 200) {
      if (response.data && Array.isArray(response.data.items)) {
        adminList.value = response.data.items;
        
        // 判断是否还有更多数据
        const totalItems = response.data.total || 0;
        const loadedItems = adminList.value.length;
        hasMore.value = loadedItems < totalItems;
      } else {
        console.error('Invalid response format:', response.data);
        adminList.value = [];
        hasMore.value = false;
      }
    } else {
      showUIFeedback.error(response.message || t('loadAdminListFailed'));
      adminList.value = [];
      hasMore.value = false;
    }
  } catch (error) {
    showUIFeedback.error(t('loadAdminListFailed'));
    console.error('Load admin list failed:', error);
    adminList.value = [];
    hasMore.value = false;
  } finally {
    isInitialLoading.value = false;
  }
};

const loadMoreAdmins = async () => {
  if (isLoadingMore.value || !hasMore.value) return;
  
  try {
    isLoadingMore.value = true;
    currentPage.value++;
    
    const params = {
      page_size: pageSize,
      page: currentPage.value,
    };
    const response = await ApiAdmin.getAdminList(params);
    
    if (response.code === 200) {
      if (response.data && Array.isArray(response.data.items)) {
        // 追加新数据到现有列表
        adminList.value.push(...response.data.items);
        
        // 判断是否还有更多数据
        const totalItems = response.data.total || 0;
        const loadedItems = adminList.value.length;
        hasMore.value = loadedItems < totalItems;
      } else {
        console.error('Invalid response format:', response.data);
        hasMore.value = false;
      }
    } else {
      showUIFeedback.error(response.message || t('loadMoreFailed'));
      hasMore.value = false;
      currentPage.value--; // 回滚页码
    }
  } catch (error) {
    showUIFeedback.error(t('loadMoreFailed'));
    console.error('Load more admins failed:', error);
    hasMore.value = false;
    currentPage.value--; // 回滚页码
  } finally {
    isLoadingMore.value = false;
  }
};

// 创建管理员相关方法
const handleAdminCreated = async (adminInfo) => {
  console.log('管理员创建成功:', adminInfo);
  
  // 关闭创建弹窗
  showCreateAdmin.value = false;
  
  // 设置账户信息
  newAccountInfo.value = {
    nickname: adminInfo.nickname || '',
    email: adminInfo.email || '',
    password: adminInfo.password || ''
  };
  
  // 显示成功弹窗
  showAccountSuccess.value = true;
  
  // 重新加载管理员列表以显示新创建的管理员
  await initAdminList();
};

const handleCreateAdminClose = () => {
  showCreateAdmin.value = false;
};

const handleAccountSuccessClose = () => {
  showAccountSuccess.value = false;
  // 清空账户信息
  newAccountInfo.value = {
    nickname: '',
    email: '',
    password: ''
  };
};

const handleResetSuccessClose = () => {
  showResetSuccess.value = false;
  // 清空重置密码账户信息
  resetAccountInfo.value = {
    nickname: '',
    email: '',
    password: ''
  };
};

// 数据解析区域
const formatDate = (dateString) => {
  if (!dateString) return '';
  return convertUtcToLocal(dateString, DATE_FORMATS.FULL_DATETIME);
};
</script>

