<template>
  <mobile-bottom-sheet
    ref="bottomSheetRef"
    @onStateChange="handleStateChange"
    @onOpened="handleOpened"
    @onClosed="handleClosed"
    :showDragIndicator="false"
    :maskClosable="true"
  >
    <div 
      ref="accountSuccessSheetRef" 
      class="account-success-sheet"
      @scroll="handleScroll"
      @touchstart="handleTouchStart"
      @touchmove="handleTouchMove"
      @touchend="handleTouchEnd"
    >
      <!-- 头部导航区域 -->
      <div 
        class="sheet-header"
        @touchstart="handleHeaderTouchStart"
        @touchmove="handleHeaderTouchMove"
        @touchend="handleHeaderTouchEnd"
      >
        <mobile-l-img 
          src="/static/images/arrow-left.png" 
          w="20px" 
          h="20px" 
          class="back-icon" 
          @click="handleClose" 
        />
        <div class="page-title">{{ pageTitle }}</div>
        <div class="placeholder"></div>
      </div>

      <!-- 成功状态图标 -->
      <div class="success-icon-container">
        <div class="success-checkmark">✓</div>
      </div>

      <!-- 提示文本 -->
      <p class="success-message">
        {{ $t('accountInfoCopiedToClipboard') }}
      </p>

      <!-- 账户信息展示区域 -->
      <div class="account-info-section">
        <!-- 昵称信息 -->
        <div class="account-info-item">
          <span class="info-label">{{ $t('nickname') }}</span>
          <span class="info-value">{{ accountInfo.nickname }}</span>
        </div>

        <!-- 邮箱信息 -->
        <div class="account-info-item">
          <span class="info-label">{{ $t('email') }}</span>
          <span class="info-value">{{ accountInfo.email }}</span>
        </div>

        <!-- 密码信息 -->
        <div class="account-info-item no-border">
          <span class="info-label">{{ $t('password') }}</span>
          <span class="info-value password-text">{{ accountInfo.password }}</span>
        </div>
      </div>

      <!-- 操作按钮区域 -->
      <div class="action-buttons">
        <div 
          class="copy-button" 
          :class="{ 'disabled': copying }"
          @click="handleCopyAccount"
        >
          {{ copying ? $t('copying') : $t('copy') }}
        </div>
      </div>
    </div>
  </mobile-bottom-sheet>
</template>

<script setup>
// 引入区域
import { ref, reactive, computed, watch, onMounted, nextTick } from 'vue';
import { useI18n } from 'vue-i18n';
import MobileLImg from '@/mobile/components/mobile-l-img.vue';
import MobileBottomSheet, { SHEET_STATES } from '@/mobile/components/layout/mobile-bottom-sheet.vue';
import { copy } from '@/utils/util';
import { showMessageSuccess, showMessageError } from '@/utils/mobile-ui-feedback';

// props 区域
const props = defineProps({
  visible: {
    type: Boolean,
    default: false
  },
  type: {
    type: String,
    default: 'create', // 'create' | 'reset'
    validator: (value) => ['create', 'reset'].includes(value)
  },
  nickname: {
    type: String,
    default: ''
  },
  email: {
    type: String,
    default: ''
  },
  password: {
    type: String,
    default: ''
  }
});

// emits 区域
const emit = defineEmits(['update:visible', 'onClose', 'onOpened', 'onClosed']);

// 变量区域
const { t } = useI18n();
const bottomSheetRef = ref(null);
const accountSuccessSheetRef = ref(null);

// 触摸事件相关变量
const touchStartY = ref(0);
const touchCurrentY = ref(0);
const isDragging = ref(false);
const isInAccountSuccessSheet = ref(false);
const isHeaderDragging = ref(false);
const TOUCH_THRESHOLD = 30; // 触发状态切换的滑动阈值（px）

// 业务逻辑变量
const copying = ref(false);

// 响应式变量
const accountInfo = reactive({
  nickname: props.nickname,
  email: props.email,
  password: props.password
});

// 计算属性区域
const visible = computed({
  get: () => props.visible,
  set: (value) => emit('update:visible', value)
});

const copyContent = computed(() => {
  return `${t('nickname')}: ${accountInfo.nickname}\n${t('email')}: ${accountInfo.email}\n${t('password')}: ${accountInfo.password}`;
});

const pageTitle = computed(() => {
  return props.type === 'create' 
    ? t('accountCreatedSuccessfully')
    : t('mobilePasswordResetSuccessfully');
});

// watch 区域
watch(() => props.visible, (newValue) => {
  if (newValue) {
    // 显示时直接展开到全屏
    nextTick(() => {
      bottomSheetRef.value?.expandUp(SHEET_STATES.FULL);
    });
  } else {
    // 隐藏时收缩
    bottomSheetRef.value?.shrinkDown(SHEET_STATES.HIDDEN);
  }
}, { immediate: true });

// 监听props变化更新accountInfo
watch(() => [props.nickname, props.email, props.password], () => {
  accountInfo.nickname = props.nickname;
  accountInfo.email = props.email;
  accountInfo.password = props.password;
}, { immediate: true });

// 点击事件区域
const handleClose = () => {
  emit('onClose');
  visible.value = false;
};

// 自定义事件区域
const handleScroll = () => {
  // 滚动事件处理
};

// 触摸事件处理
const handleTouchStart = (e) => {
  touchStartY.value = e.touches[0].clientY;
  touchCurrentY.value = e.touches[0].clientY;
  isDragging.value = false;
  
  // 判断触摸位置是否在account-success-sheet内
  if (accountSuccessSheetRef.value) {
    const rect = accountSuccessSheetRef.value.getBoundingClientRect();
    const touchX = e.touches[0].clientX;
    const touchY = e.touches[0].clientY;
    
    isInAccountSuccessSheet.value = (
      touchX >= rect.left &&
      touchX <= rect.right &&
      touchY >= rect.top &&
      touchY <= rect.bottom
    );
  } else {
    isInAccountSuccessSheet.value = false;
  }
};

const handleTouchMove = (e) => {
  touchCurrentY.value = e.touches[0].clientY;
  const deltaY = touchCurrentY.value - touchStartY.value;
  
  // 如果移动距离超过阈值，认为是拖拽
  if (Math.abs(deltaY) > 5 && !isDragging.value) {
    isDragging.value = true;
  }
};

const handleTouchEnd = (e) => {
  if (!isDragging.value || !bottomSheetRef.value) {
    resetTouchState();
    return;
  }
  
  const deltaY = touchCurrentY.value - touchStartY.value;
  const currentState = bottomSheetRef.value.currentState;
  
  // 判断滑动逻辑
  if (isInAccountSuccessSheet.value && !isHeaderDragging.value) {
    // 在account-success-sheet内滑动，检查滚动位置
    if (!accountSuccessSheetRef.value) {
      resetTouchState();
      return;
    }
    
    const scrollTop = accountSuccessSheetRef.value.scrollTop;
    const scrollHeight = accountSuccessSheetRef.value.scrollHeight;
    const clientHeight = accountSuccessSheetRef.value.clientHeight;
    const isAtTop = scrollTop <= 5;
    const isAtBottom = scrollTop + clientHeight >= scrollHeight - 5;
    
    // 在顶部向下拖拽超过阈值
    if (isAtTop && deltaY > TOUCH_THRESHOLD) {
      handleStateSwitch(deltaY, currentState);
    }
    // 在底部向下拖拽超过阈值
    else if (isAtBottom && deltaY > TOUCH_THRESHOLD) {
      handleStateSwitch(deltaY, currentState);
    }
  } else {
    // 不在account-success-sheet内滑动或者是header拖拽，直接处理
    if (Math.abs(deltaY) > TOUCH_THRESHOLD) {
      handleStateSwitch(deltaY, currentState);
    }
  }
  
  resetTouchState();
};

// Header特殊拖拽处理
const handleHeaderTouchStart = (e) => {
  isHeaderDragging.value = true;
  handleTouchStart(e);
};

const handleHeaderTouchMove = (e) => {
  if (isHeaderDragging.value) {
    handleTouchMove(e);
  }
};

const handleHeaderTouchEnd = (e) => {
  if (isHeaderDragging.value) {
    handleTouchEnd(e);
  }
  isHeaderDragging.value = false;
};

// 状态切换处理
const handleStateSwitch = (deltaY, currentState) => {
  if (deltaY > 0) {
    // 向下滑动，关闭弹窗
    visible.value = false;
  }
  // 这个页面不需要向上展开的逻辑，因为它是成功页面
};

// 重置触摸状态
const resetTouchState = () => {
  touchStartY.value = 0;
  touchCurrentY.value = 0;
  isDragging.value = false;
  isInAccountSuccessSheet.value = false;
  isHeaderDragging.value = false;
};

const handleStateChange = (newState) => {
  // 当弹窗状态变为隐藏时，更新父组件的 visible 状态
  if (newState === SHEET_STATES.HIDDEN) {
    emit('update:visible', false);
  }
};

const handleOpened = () => {
  // 弹窗打开时的回调
  emit('onOpened');
  resetTouchState();
};

const handleClosed = () => {
  // 弹窗关闭时的回调
  emit('onClosed');
  visible.value = false;
  resetTouchState();
};

// 业务逻辑区域
const handleCopyAccount = () => {
  if (copying.value) {
    return;
  }

  try {
    copying.value = true;
    copy(copyContent.value);
    showMessageSuccess(t('copySuccess'));
    
    // 复制成功后延迟关闭弹窗，让用户看到成功提示
    setTimeout(() => {
      handleClose();
    }, 500);
  } catch (error) {
    console.error('Copy failed:', error);
    showMessageError(t('copyFailed'));
  } finally {
    copying.value = false;
  }
};

// 初始化方法区域
const initData = () => {
  // 初始化逻辑
  console.log('Account success sheet initialized');
};

// 周期函数区域
onMounted(() => {
  initData();
});

// 导出区域
defineExpose({
  handleClose
});
</script>

